import { MeshStandardNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const root = new THREE.Group();
  const timelines = [];
  const cleanups = [];
  let disposed = false;
  let assetRoot = null;
  let accentMaterials = [];

  root.name = config.id || config.name || 'ornamental-divider';
  root.userData.handlers = {};

  const ink = '#16161d';
  const paper = '#e8ecf2';
  const accent = '#ff2a38';
  const surface = '#0b0b10';

  const backingMaterial = new MeshStandardNodeMaterial({
    color: ink,
    roughness: 0.72,
    metalness: 0.38
  });

  const backing = new THREE.Mesh(
    new THREE.BoxGeometry(2.7, 0.12, 0.035),
    backingMaterial
  );
  backing.name = 'machined-divider-backplate';
  backing.position.z = -0.08;
  root.add(backing);

  const ruleMaterial = new MeshStandardNodeMaterial({
    color: paper,
    roughness: 0.58,
    metalness: 0.52
  });

  const rule = new THREE.Mesh(
    new THREE.BoxGeometry(2.35, 0.018, 0.045),
    ruleMaterial
  );
  rule.name = 'machined-divider-rule';
  rule.position.z = 0.005;
  root.add(rule);

  const jewelMaterial = new MeshStandardNodeMaterial({
    color: accent,
    emissive: accent,
    emissiveIntensity: 1.35,
    roughness: 0.42,
    metalness: 0.28
  });
  accentMaterials.push(jewelMaterial);

  const jewel = new THREE.Mesh(
    new THREE.OctahedronGeometry(0.09, 1),
    jewelMaterial
  );
  jewel.name = 'center-signal-jewel';
  jewel.position.z = 0.075;
  root.add(jewel);

  const focusMaterial = new MeshStandardNodeMaterial({
    color: accent,
    emissive: accent,
    emissiveIntensity: 1.05,
    transparent: true,
    opacity: 0,
    roughness: 0.55,
    metalness: 0.32
  });
  accentMaterials.push(focusMaterial);

  const focusEdge = new THREE.Mesh(
    new THREE.BoxGeometry(2.58, 0.026, 0.012),
    focusMaterial
  );
  focusEdge.name = 'focus-accent-edge';
  focusEdge.position.z = 0.09;
  root.add(focusEdge);

  const setAssetMaterials = (object) => {
    object.traverse((child) => {
      if (!child.isMesh) return;
      child.castShadow = true;
      child.receiveShadow = true;
    });
  };

  if (config.meshUrl && ctx.glbLoader?.loadGLB) {
    ctx.glbLoader.loadGLB(config.meshUrl).then((gltf) => {
      if (disposed || !gltf?.scene) return;
      assetRoot = gltf.scene;
      assetRoot.name = 'ornamental-divider-asset';
      setAssetMaterials(assetRoot);
      root.add(assetRoot);
    });
  }

  const rise = () => {
    const tween = gsap.to(root.position, {
      y: '+=0.15',
      duration: 0.7,
      ease: 'power3.out',
      overwrite: true
    });
    timelines.push(tween);
  };

  const settle = () => {
    const tween = gsap.to(root.position, {
      y: '-=0.15',
      duration: 0.5,
      ease: 'power3.out',
      overwrite: true
    });
    timelines.push(tween);
  };

  root.userData.handlers.hover = (active = true) => {
    if (active) {
      rise();
      const edgeTween = gsap.to(focusMaterial, {
        opacity: 0.72,
        duration: 0.3,
        ease: 'power2.out',
        overwrite: true
      });
      timelines.push(edgeTween);
    } else {
      settle();
      const edgeTween = gsap.to(focusMaterial, {
        opacity: 0,
        duration: 0.3,
        ease: 'power2.out',
        overwrite: true
      });
      timelines.push(edgeTween);
    }
  };

  root.userData.handlers.click = () => {
    const press = gsap.timeline();
    press.to(root.scale, {
      x: 0.97,
      y: 0.97,
      z: 0.97,
      duration: 0.12,
      ease: 'power2.out'
    }).to(root.scale, {
      x: 1,
      y: 1,
      z: 1,
      duration: 0.45,
      ease: 'back.out(2.2)'
    });
    timelines.push(press);
    ctx.emit('hub-home.select', {
      node: root.name
    });
  };

  root.userData.handlers.focus = (active = true) => {
    const tween = gsap.to(focusMaterial, {
      opacity: active ? 1 : 0,
      duration: 0.22,
      ease: 'power2.out',
      overwrite: true
    });
    timelines.push(tween);
  };

  root.userData.cleanup = () => {
    if (disposed) return;
    disposed = true;

    for (const timeline of timelines) {
      timeline?.kill?.();
    }

    for (const cleanup of cleanups) {
      cleanup?.();
    }

    root.traverse((child) => {
      if (!child.isMesh) return;
      child.geometry?.dispose?.();

      const materials = Array.isArray(child.material)
        ? child.material
        : [child.material];

      for (const material of materials) {
        if (!material) continue;
        for (const key of Object.keys(material)) {
          const value = material[key];
          if (value?.isTexture) value.dispose?.();
        }
        material.dispose?.();
      }
    });
  };

  const primitives = config.cinematicPrimitives ?? [];
  for (const primitive of primitives) {
    const apply = ctx.primitives?.[primitive.name];
    if (typeof apply !== 'function') continue;
    const result = apply(root, primitive.params);
    if (result?.timeline) timelines.push(result.timeline);
    if (result?.cleanup) cleanups.push(result.cleanup);
  }

  return root;
}
